9: /** Copy JSON data without invoking getters, toJSON, inherited code or mutable caller objects. */
10: function snapshotJson(
11:   value: unknown,
12:   ancestors: Set<object>,
13:   depth: number,
14:   maxDepth: number,
15:   forbidKeys: boolean,
16: ): unknown {
17:   if (depth > maxDepth) throw new Error("JSON nesting limit");
18:   if (value === null || typeof value === "string" || typeof value === "boolean") return value;
19:   if (typeof value === "number" && Number.isFinite(value)) return value;
20:   if (!value || typeof value !== "object" || ancestors.has(value))
21:     throw new Error("Invalid JSON data");
22:   const prototype = Object.getPrototypeOf(value);
23:   if (
24:     (!Array.isArray(value) && prototype !== Object.prototype && prototype !== null) ||
25:     Object.getOwnPropertySymbols(value).length
26:   )
27:     throw new Error("Invalid JSON object");
28:   ancestors.add(value);
29:   try {
30:     const descriptors = Object.getOwnPropertyDescriptors(value);
31:     if (Array.isArray(value)) {
32:       if (value.length > 100_000) throw new Error("JSON array limit");
33:       return Array.from({ length: value.length }, (_, index) => {
34:         const descriptor = descriptors[String(index)];
35:         if (descriptor && !Object.hasOwn(descriptor, "value")) throw new Error("JSON accessor");
36:         return descriptor?.value === undefined
37:           ? null
38:           : snapshotJson(descriptor.value, ancestors, depth + 1, maxDepth, forbidKeys);
39:       });
40:     }
41:     const result: Record<string, unknown> = Object.create(null);
42:     for (const [key, descriptor] of Object.entries(descriptors)) {
43:       if (!descriptor.enumerable) continue;
44:       if (
45:         !Object.hasOwn(descriptor, "value") ||
46:         (forbidKeys && ["__proto__", "constructor", "prototype"].includes(key))
47:       )
48:         throw new Error("Invalid JSON property");
49:       if (descriptor.value !== undefined)
50:         result[key] = snapshotJson(descriptor.value, ancestors, depth + 1, maxDepth, forbidKeys);
51:     }
52:     return result;
53:   } finally {
54:     ancestors.delete(value);
55:   }
56: }
