58: function matches(schema: LinkValueSchema, value: unknown, depth = 0): boolean {
59:   if (depth > 20) return false;
60:   if (schema.enum && !schema.enum.includes(value as string)) return false;
61:   if (schema.anyOf && !schema.anyOf.some((item) => matches(item, value, depth + 1))) return false;
62:   if (schema.oneOf && schema.oneOf.filter((item) => matches(item, value, depth + 1)).length !== 1)
63:     return false;
64:   if (schema.type === "null") return value === null;
65:   if (schema.type === "boolean") return typeof value === "boolean";
66:   if (schema.type === "string")
67:     return (
68:       typeof value === "string" &&
69:       value.length >= (schema.minLength ?? 0) &&
70:       value.length <= (schema.maxLength ?? Infinity) &&
71:       (!schema.pattern || new RegExp(schema.pattern).test(value))
72:     );
73:   if (schema.type === "number" || schema.type === "integer")
74:     return (
75:       typeof value === "number" &&
76:       Number.isFinite(value) &&
77:       (schema.type !== "integer" || Number.isSafeInteger(value)) &&
78:       value >= (schema.minimum ?? -Infinity) &&
79:       value <= (schema.maximum ?? Infinity)
80:     );
81:   if (schema.type === "array")
82:     return (
83:       Array.isArray(value) &&
84:       value.length >= (schema.minItems ?? 0) &&
85:       value.length <= (schema.maxItems ?? Infinity) &&
86:       (!schema.items || value.every((item) => matches(schema.items!, item, depth + 1)))
87:     );
88:   if (schema.type === "object" || schema.required || schema.properties) {
89:     if (!value || typeof value !== "object" || Array.isArray(value)) return false;
90:     const record = value as Record<string, unknown>;
91:     if (schema.required?.some((key) => !Object.hasOwn(record, key))) return false;
92:     return Object.entries(record).every(([key, item]) => {
93:       if (["__proto__", "prototype", "constructor"].includes(key)) return false;
94:       const property =
95:         schema.properties && Object.hasOwn(schema.properties, key)
96:           ? schema.properties[key]
97:           : undefined;
98:       return property ? matches(property, item, depth + 1) : schema.additionalProperties !== false;
99:     });
100:   }
101:   return true;
102: }
