115: export function snapshotLinkOperationInput(
116:   contract: LinkOperationContract,
117:   input: unknown,
118: ): Record<string, unknown> {
119:   let detached: unknown;
120:   let size = Infinity;
121:   try {
122:     detached = snapshotJson(input, new Set(), 0, contract.limits.inputDepth, true);
123:     size = new TextEncoder().encode(JSON.stringify(detached)).length;
124:   } catch {
125:     /* Reject cyclic/non-JSON inputs. */
126:   }
127:   if (size > contract.limits.inputBytes || !matches(contract.inputSchema, detached))
128:     throw new LinkOperationError(
129:       "invalid_input",
130:       `Invalid parameters for ${contract.operationId}.`,
131:     );
132:   return detached as Record<string, unknown>;
133: }
