135: export function assertLinkOperationResult(contract: LinkOperationContract, result: unknown): void {
136:   let detached: unknown;
137:   let size = Infinity;
138:   try {
139:     detached = snapshotJson(result, new Set(), 0, contract.limits.responseDepth, false);
140:     size = new TextEncoder().encode(JSON.stringify(detached)).length;
141:   } catch {
142:     /* Fail closed. */
143:   }
144:   if (size > contract.limits.responseBytes || !matches(contract.outputSchema, detached))
145:     throw new LinkOperationError("invalid_result", `Invalid result for ${contract.operationId}.`);
146: }
