148: /** Applies equally to direct API, CLI, MCP and broker adapters. Missing identity fails closed. */
149: export function filterLinkOperationResult(
150:   contract: LinkOperationContract,
151:   result: unknown,
152:   authorization: LinkOperationAuthorization,
153: ): unknown {
154:   if (
155:     authorization.resources.kind === "upstream-scoped" ||
156:     contract.resourcePolicy.source !== "grant-filtered"
157:   )
158:     return result;
159:   const filter = contract.resourcePolicy.resultFilter;
160:   const group = authorization.resources.groups.find(
161:     (item) => item.id === contract.resourcePolicy.group,
162:   );
163:   if (!filter || !group || !result || typeof result !== "object" || Array.isArray(result))
164:     throw new LinkOperationError(
165:       "invalid_result",
166:       "The operation cannot prove its result resource scope.",
167:     );
168:   const values = (result as Record<string, unknown>)[filter.collection];
169:   if (!Array.isArray(values))
170:     throw new LinkOperationError(
171:       "invalid_result",
172:       "The operation returned an invalid resource listing.",
173:     );
174:   const normalize = (value: string) => {
175:     const normalized = filter.stripHyphens ? value.replaceAll("-", "") : value;
176:     return filter.lowercase ? normalized.toLowerCase() : normalized;
177:   };
178:   const allowed = new Set(group.items.map((item) => normalize(item.id)));
179:   return {
180:     ...result,
181:     [filter.collection]: values.filter((item: unknown) => {
182:       let value = item;
183:       for (const key of filter.identityPath)
184:         value =
185:           value && typeof value === "object" ? (value as Record<string, unknown>)[key] : undefined;
186:       return (
187:         (typeof value === "string" || typeof value === "number") &&
188:         allowed.has(normalize(String(value)))
189:       );
190:     }),
191:   };
192: }
