194: /** Content traits never decide whether an operation needs authorization. */
195: export function assertLinkOperationAuthorized(
196:   contract: LinkOperationContract,
197:   params: Record<string, unknown>,
198:   authorization: LinkOperationAuthorization,
199: ): void {
200:   const recipe = getLinkConnectionRecipe(authorization.recipeId);
201:   if (
202:     !recipe ||
203:     authorization.providerId !== contract.providerId ||
204:     !authorization.connectionId ||
205:     !authorization.accountId ||
206:     !authorization.authorityRevision ||
207:     !contract.executors.includes(recipe.executor) ||
208:     !authorization.capabilityIds.includes(contract.operationId)
209:   )
210:     throw new LinkOperationError(
211:       "permission_denied",
212:       "The selected connection does not authorize this operation.",
213:     );
214:   if (contract.effect === "write" && recipe.executor === "cli")
215:     throw new LinkOperationError(
216:       "permission_denied",
217:       "CLI connections do not support verified writes.",
218:     );
219:   if (authorization.resources.kind === "upstream-scoped") {
220:     if (recipe.route === "brokered")
221:       throw new LinkOperationError(
222:         "permission_denied",
223:         "Broker operations require an explicit resource grant.",
224:       );
225:     return;
226:   }
227:   const group = authorization.resources.groups.find(
228:     (item) => item.id === contract.resourcePolicy.group,
229:   );
230:   if (!group)
231:     throw new LinkOperationError(
232:       "resource_not_granted",
233:       "The selected resource group is not authorized.",
234:     );
235:   if (contract.resourcePolicy.source !== "input") return; // The executor must filter listing results to this group.
236:   const selector = contract.resourcePolicy.selector;
237:   if (!selector)
238:     throw new LinkOperationError(
239:       "resource_not_granted",
240:       "The operation has no reviewed resource selector.",
241:     );
242:   let selected: string;
243:   if (selector.kind === "joined") {
244:     const parts = selector.fields.map((field) => params[field]);
245:     if (parts.some((part) => typeof part !== "string" || !part))
246:       throw new LinkOperationError("invalid_input", "An explicit resource target is required.");
247:     selected = parts.join(selector.separator ?? "/");
248:   } else {
249:     const value = selector.fields.map((field) => params[field]).find((item) => item !== undefined);
250:     if (typeof value !== "string" || !value)
251:       throw new LinkOperationError("invalid_input", "An explicit resource target is required.");
252:     selected = value;
253:     if (selector.kind === "slack-permalink" || /^https?:\/\//i.test(value)) {
254:       let url: URL;
255:       try {
256:         url = new URL(value);
257:       } catch {
258:         throw new LinkOperationError("invalid_input", "Invalid resource URL.");
259:       }
260:       const allowedHost =
261:         selector.kind === "slack-permalink"
262:           ? /^[a-z0-9-]+\.slack\.com$/.test(url.hostname)
263:           : selector.urlHosts?.includes(url.hostname);
264:       if (url.protocol !== "https:" || url.username || url.password || url.port || !allowedHost)
265:         throw new LinkOperationError("invalid_input", "Invalid resource URL.");
266:       selected = url.pathname.split("/").filter(Boolean)[selector.urlPathIndex ?? 1] ?? "";
267:     }
268:   }
269:   const normalize = (value: string) => {
270:     const normalized = selector.stripHyphens ? value.replaceAll("-", "") : value;
271:     return selector.lowercase ? normalized.toLowerCase() : normalized;
272:   };
273:   if (!group.items.some((item) => normalize(item.id) === normalize(selected)))
274:     throw new LinkOperationError(
275:       "resource_not_granted",
276:       "The resource is outside this connection's grant.",
277:     );
278: }
